#include <vector>
#include <omp.h>

double productWithInverses(std::vector<double> const& x) {
    double product = 1.0;
    #pragma omp parallel for reduction(*:product)
    for (std::size_t i = 0; i < x.size(); ++i) {
        // For even indices keep x[i]; for odd indices use its reciprocal.
        double term = (i % 2 == 0) ? x[i] : 1.0 / x[i];
        product *= term;
    }
    return product;
}
